<fieldset><legend><?=e(jt('stops'))?></legend><p><?=e(jt('order'))?></p><?php foreach($catalog as $x):?><div data-journey-stop><label class="check"><input type="checkbox" name="stops[]" value="<?=e($x['id'])?>" <?=in_array($x['id'],$selected,true)?'checked':''?>> <?=e($x['title'])?> · <?=e(offerLabel($x['cost']==='free'?'free':'check_price'))?></label><button type="button" data-journey-up><?=e(jt('up'))?></button><button type="button" data-journey-down><?=e(jt('down'))?></button><label class="check"><input type="checkbox" name="optional[]" value="<?=e($x['id'])?>" <?=in_array($x['id'],$form['optional']??[],true)?'checked':''?>> <?=e(jt('optional'))?></label><details><summary><?=e(jt('reservation'))?></summary><?php foreach(['start','end','checkin'] as $ak):$field=$ak==='checkin'?'checkin_by':$ak;?><label><?=e(jt('anchor_'.$ak))?><input type="time" name="anchor_<?=$ak?>[<?=e($x['id'])?>]" value="<?=e($form['anchors'][$x['id']][$field]??'')?>" data-stop-input></label><?php endforeach?><label class="check"><input type="checkbox" name="paid[]" value="<?=e($x['id'])?>" <?=in_array($x['id'],$form['paid']??[],true)?'checked':''?> data-stop-input> <?=e(jt('paid'))?></label></details></div><?php endforeach?></fieldset>
