<?php $shown=$saved??$calculation;if($shown):$r=$shown['result'];?><section id="journey-result" tabindex="-1" class="form-panel" aria-live="polite"><h2><?=e(jt($r['status']))?></h2><?php if(APP_ENV==='local'&&jq("SELECT 1 FROM journey_facts WHERE actor='fixture' LIMIT 1")->fetchColumn()):?><p class="notice"><?=e(jt('synthetic'))?></p><?php endif?><p><?=e(jt('disclaimer'))?></p><ul><?php foreach(array_merge($r['data_gaps'],$r['unmet_constraints']) as $reason):?><li><?=e(jt($reason))?></li><?php endforeach?></ul><dl><dt><?=e(jt('budget'))?></dt><dd><?=$r['cost_minor']===null?e(jt('unknown')):e(number_format($r['cost_minor']/100,2).' '.$shown['input']['currency'])?></dd><dt><?=e(jt('walk'))?></dt><dd><?=in_array('WALKING_LEG_UNKNOWN',$r['data_gaps'],true)?e(jt('unknown')):(int)$r['walking_meters']?></dd><dt><?=e(jt('remaining'))?></dt><dd><?=($r['remaining_cash_minor']??null)===null?e(jt('unknown')):e(number_format($r['remaining_cash_minor']/100,2).' '.$shown['input']['currency'])?></dd><dt><?=e(jt('walking_time'))?></dt><dd><?=in_array('WALKING_LEG_UNKNOWN',$r['data_gaps'],true)?e(jt('unknown')):(int)$r['walking_minutes']?></dd><dt><?=e(jt('visit_time'))?></dt><dd><?=(int)$r['visit_minutes']?></dd><dt><?=e(jt('waiting_time'))?></dt><dd><?=(int)($r['wait_minutes']+$r['checkin_minutes'])?></dd></dl><ol><?php foreach($r['timeline'] as $stop):?><li><?=e($stop['at']==='@end'?jt('end_place'):(networkItemForLanguage($stop['at'],siteLanguage())??jt('unknown')))?> · <?=e((new DateTimeImmutable('@'.$stop['arrive']))->setTimezone(new DateTimeZone($shown['input']['timezone']))->format('H:i'))?> — <?=e((new DateTimeImmutable('@'.$stop['depart']))->setTimezone(new DateTimeZone($shown['input']['timezone']))->format('H:i'))?><?php if($stop['at']!=='@end'):?><br><small><?=e(jt('group_cost'))?>: <?=($stop['cost_minor']??null)===null?e(jt('unknown')):e(number_format($stop['cost_minor']/100,2).' '.$shown['input']['currency'])?></small><?php endif?></li><?php endforeach?></ol>
<?php if(!$saved):?><form method="post"><?=csrf()?><input type="hidden" name="journey_action" value="save"><input type="hidden" name="payload" value="<?=e(json_encode($shown['input']))?>"><label><?=e(jt('name'))?><input name="title" maxlength="120" value="<?=e(jt('title'))?>" required></label><button class="button"><?=e(jt('save'))?></button></form><?php else:?><p><?=e(jt('saved'))?> · <?=(int)$saved['revision']?></p><form method="post"><?=csrf()?><input type="hidden" name="journey_action" value="replan"><input type="hidden" name="trip" value="<?=e($saved['id'])?>"><input type="hidden" name="revision" value="<?=(int)$saved['revision']?>"><label><?=e(jt('progress'))?><select name="progress_count"><option value="0">—</option><?php foreach($saved['input']['stops'] as $n=>$id):?><option value="<?=$n+1?>"><?=e(networkItemForLanguage($id,siteLanguage())??jt('unknown'))?></option><?php endforeach?></select></label><label><?=e(jt('now'))?><input type="time" name="current_time"></label><button class="button"><?=e(jt('replan'))?></button></form><?php if($saved['revision']>1):?><form method="post"><?=csrf()?><input type="hidden" name="journey_action" value="undo"><input type="hidden" name="trip" value="<?=e($saved['id'])?>"><input type="hidden" name="revision" value="<?=(int)$saved['revision']?>"><select name="restore"><?php foreach(jq('SELECT revision FROM journey_versions WHERE trip=? ORDER BY revision DESC',[$saved['id']]) as $ver):?><option><?=(int)$ver['revision']?></option><?php endforeach?></select><button><?=e(jt('undo'))?></button></form><?php endif?><?php endif?></section><?php endif?>
<?php if($proposal):?><section class="form-panel"><h2><?=e(jt('replan'))?></h2><p><?=e(jt('BOUNDED_SEARCH_ONLY'))?></p><?php if(!$proposal['options']):?><p><?=e(jt($proposal['status']))?></p><?php endif?><?php foreach($proposal['options'] as $o):?><form method="post"><?=csrf()?><input type="hidden" name="journey_action" value="apply"><input type="hidden" name="trip" value="<?=e($_POST['trip'])?>"><input type="hidden" name="revision" value="<?=(int)$_POST['revision']?>"><input type="hidden" name="proposal" value="<?=e($proposal['proposal_id'])?>"><input type="hidden" name="selection" value="<?=e($o['id'])?>"><input type="hidden" name="idempotency_key" value="<?=e(bin2hex(random_bytes(16)))?>"><p><?=e(jt('walk'))?>: <?=(int)$o['calculation']['result']['walking_meters']?> · <?=e(jt('budget'))?>: <?=e(number_format($o['calculation']['result']['cost_minor']/100,2))?></p><ol><?php foreach($o['calculation']['input']['stops'] as $oid):?><li><?=e(networkItemForLanguage($oid,siteLanguage())??jt('unknown'))?></li><?php endforeach?></ol><p><?=e(jt('cost_diff'))?>: <?=e($o['diff']['cost_minor']===null?jt('unknown'):number_format($o['diff']['cost_minor']/100,2).' '.$o['calculation']['input']['currency'])?> · <?=e(jt('walk_diff'))?>: <?=(int)$o['diff']['walking_minutes']?> · <?=e(jt('time_diff'))?>: <?=(int)$o['diff']['elapsed_minutes']?></p><button class="button"><?=e(jt('apply'))?></button></form><?php endforeach?></section><?php endif?>
<section class="form-panel"><h2><?=e(jt('archive'))?></h2><form method="get"><input type="hidden" name="lang" value="<?=e(siteLanguage())?>"><label><?=e(jt('search'))?><input name="q" value="<?=e($_GET['q']??'')?>" maxlength="100"></label><button><?=e(jt('search'))?></button></form><?php foreach(jq('SELECT * FROM journey_trips WHERE principal=? AND locale=? ORDER BY updated DESC LIMIT 100',[journeyPrincipal(),siteLanguage()]) as $row):$archive=journeyVersion($row['id'],(int)$row['revision']);$search=$row['title'].' '.($archive['input']['service_date']??'').' '.($archive['input']['tags']??'');foreach($archive['input']['stops'] as $id)$search.=' '.(networkItemForLanguage($id,siteLanguage())??'');if(!empty($_GET['q'])&&mb_strpos(mb_strtolower($search),mb_strtolower((string)$_GET['q']))===false)continue;?><p><a href="<?=e(languageUrl('/day-plan/?trip='.$row['id'],siteLanguage()))?>"><?=e($row['title'])?></a> · <?=date('Y-m-d',$row['updated'])?></p><?php endforeach?></section>

